import type { JobPostingListing } from "./jobPostings";

/**
 * 공고 한 장(/jobs/:slug) 본문과 분석 폼 채우기에 쓰는 내용. 공고 페이지·분석 폼·지원서 화면(모두 지연 청크)만 import 한다.
 * 홈 번들에 싣지 않는다 — 목록용 최소 필드는 constants/jobPostings.ts.
 *
 * 문장은 블로그 공고 글(.agents/blog-job-posts/drafts, 공식 채용 페이지로 확인한 것)에서 옮긴다. 줄바꿈("\n")은 문단 나눔이다.
 * 공고에 적힌 사실(모집 직무·자격·전형·일정)과 주요 특징만 싣는다. 자소서 문항·쓰는 법은 싣지 않는다 — 직무마다 달라
 * 매번 확인할 게 너무 많아진다(10-09).
 */

export type JobPostingDetail = {
  /** 검색 설명(160자 이하) */
  description: string;
  keywords: string;
  /** 제목 아래 한 문단: 이번 공고에서 제일 눈에 띄는 점 */
  highlight: string;
  /**
   * 값이 배열이거나 " · " 로 이어 쓴 문자열이면 한 줄씩 목록으로 보인다.
   * href 가 있으면 첫 줄을 그 주소로 건다(접수처 → 실제로 지원하는 사이트).
   */
  facts: readonly { label: string; value: string | readonly string[]; href?: string }[];
  /** 전형 절차. 부문마다 다르면 여러 줄(name 이 부문 이름) */
  process: readonly { name: string | null; steps: readonly string[] }[];
  /** 전형 절차 아래 한 줄 덧붙임 */
  processNote: string | null;
  /** 지원 전에 확인할 것 */
  checks: readonly string[];
  /** 공식 채용 페이지 */
  source: { label: string; url: string };
};

